-- Pro/Contra Antwortpaare im Stil von "Hubert Hubertikus" für die Fragen 1431–1466
-- Jede Frage erhält genau zwei Zeilen: eine Pro- (stance_llm = 'Positive')
-- und eine Contra-Antwort (stance_llm = 'Negative').
-- id wird nicht gesetzt (Annahme: serial/auto increment). delegate_id, model_used
-- und full_stance bleiben NULL, analog zu den Referenzdaten in der Anhangs-Tabelle.

BEGIN;

INSERT INTO political_answers
    (question_id, delegate_id, answer, stance_llm, is_strong_reference, model_used, created_at, full_stance)
VALUES

-- 1431: Abschiebung verurteilter Straftäter ohne weitere Menschenrechtsprüfung
(1431, NULL, 'Hubert Hubertikus befürwortet ein Recht Österreichs, verurteilte Straftäter ohne weitere Menschenrechtsprüfung abzuschieben. Er argumentiert, dass Personen, die schwere Straftaten begangen haben, ihr Bleiberecht verwirkt haben und die öffentliche Sicherheit Vorrang vor individuellen Verfahrensrechten haben muss. Langwierige Prüfverfahren würden Abschiebungen oft jahrelang verzögern und das Vertrauen der Bevölkerung in den Rechtsstaat untergraben. Für Hubertikus ist eine konsequente Durchsetzung von Recht und Ordnung entscheidend für die gesellschaftliche Sicherheit.', 'Positive', true, NULL, now(), NULL),
(1431, NULL, 'Hubert Hubertikus lehnt es entschieden ab, Straftäter ohne weitere Menschenrechtsprüfung abzuschieben. Er betont, dass der Verzicht auf eine solche Prüfung gegen völkerrechtliche Verpflichtungen und die Grundrechte jedes Menschen verstoßen würde, unabhängig von begangenen Straftaten. Ein Rechtsstaat müsse gerade in schwierigen Fällen an rechtsstaatlichen Verfahren festhalten, um Willkür und Fehlentscheidungen zu vermeiden. Hubertikus warnt davor, dass Österreich damit seine internationale Glaubwürdigkeit als Rechtsstaat aufs Spiel setzen würde.', 'Negative', true, NULL, now(), NULL),

-- 1432: Digitale Kompetenzen und KI als Pflichtfach
(1432, NULL, 'Hubert Hubertikus ist klar dafür, digitale Kompetenzen und Künstliche Intelligenz zum verpflichtenden Bestandteil des Schulunterrichts zu machen. Er sieht darin eine notwendige Anpassung an eine Arbeitswelt, die zunehmend von Digitalisierung und KI geprägt ist. Nur wer frühzeitig lerne, mit diesen Technologien kompetent und kritisch umzugehen, könne später am Arbeitsmarkt bestehen. Für Hubertikus ist digitale Bildung damit eine Frage der Chancengerechtigkeit.', 'Positive', true, NULL, now(), NULL),
(1432, NULL, 'Hubert Hubertikus spricht sich gegen eine verpflichtende Verankerung digitaler Kompetenzen und KI im Lehrplan aus. Er befürchtet, dass Schulen dadurch überfrachtet werden und grundlegende Fähigkeiten wie Lesen, Schreiben und Rechnen zu kurz kommen. Zudem fehle vielen Lehrkräften derzeit die notwendige Ausbildung, um solche Inhalte fundiert zu vermitteln. Hubertikus plädiert stattdessen für freiwillige Zusatzangebote statt eines starren Pflichtfachs.', 'Negative', true, NULL, now(), NULL),

-- 1433: Erneuerbare Energien vs. Naturschutzgebiete
(1433, NULL, 'Hubert Hubertikus tritt dafür ein, dem Ausbau erneuerbarer Energien Vorrang vor dem Schutz von Naturschutzgebieten einzuräumen. Angesichts der Klimakrise sei eine rasche Energiewende überlebensnotwendig, und Verzögerungen durch strenge Schutzauflagen würden die Erreichung der Klimaziele gefährden. Er verweist darauf, dass langfristig auch der Naturschutz von einem stabilen Klima profitiert. Für Hubertikus überwiegt der gesellschaftliche Nutzen sauberer Energie die kurzfristigen Eingriffe in einzelne Schutzgebiete.', 'Positive', true, NULL, now(), NULL),
(1433, NULL, 'Hubert Hubertikus lehnt es ab, erneuerbaren Energien pauschal Vorrang vor dem Naturschutz einzuräumen. Er warnt, dass intakte Ökosysteme unwiederbringlich verloren gehen können, wenn Schutzgebiete für Windkraft- oder Solaranlagen geopfert werden. Klimaschutz und Artenschutz dürften nicht gegeneinander ausgespielt werden, sondern müssten sorgfältig abgewogen werden. Hubertikus fordert stattdessen eine sorgfältige Standortplanung, die beide Ziele miteinander vereinbart.', 'Negative', true, NULL, now(), NULL),

-- 1434: Reparaturfreundliche Produkte
(1434, NULL, 'Hubert Hubertikus befürwortet eine gesetzliche Pflicht für Unternehmen, Produkte reparaturfreundlicher zu gestalten. Er sieht darin einen wichtigen Beitrag zum Umweltschutz, da reparierbare Produkte Ressourcen schonen und den Elektroschrott reduzieren. Zudem würden Konsumentinnen und Konsumenten langfristig finanziell entlastet, wenn Geräte nicht mehr bei kleinsten Defekten ersetzt werden müssten. Für Hubertikus ist das ein notwendiger Schritt hin zu einer nachhaltigeren Kreislaufwirtschaft.', 'Positive', true, NULL, now(), NULL),
(1434, NULL, 'Hubert Hubertikus ist gegen eine gesetzliche Verpflichtung zur Reparaturfreundlichkeit von Produkten. Er befürchtet, dass solche Vorgaben die Innovationsfähigkeit der Unternehmen einschränken und zu höheren Produktionskosten führen, die letztlich die Konsumentinnen und Konsumenten tragen müssten. Der Markt biete bereits Anreize für reparaturfreundliches Design, etwa durch die Nachfrage umweltbewusster Kundschaft. Hubertikus setzt lieber auf freiwillige Selbstverpflichtungen der Industrie als auf staatliche Vorschriften.', 'Negative', true, NULL, now(), NULL),

-- 1435: Bürokratische Hürden bei Selbsttötung
(1435, NULL, 'Hubert Hubertikus befürwortet strengere bürokratische Hürden für den Zugang zur Selbsttötung. Er argumentiert, dass solche Hürden als Schutzmechanismus dienen und übereilte Entscheidungen in Krisensituationen verhindern können. Eine sorgfältige Prüfung gebe Betroffenen Zeit, alternative Hilfsangebote wie psychologische Betreuung in Anspruch zu nehmen. Für Hubertikus steht der Schutz des Lebens im Zweifel über der schnellen Verfügbarkeit dieser Option.', 'Positive', true, NULL, now(), NULL),
(1435, NULL, 'Hubert Hubertikus lehnt strengere bürokratische Hürden bei der Selbsttötung entschieden ab. Er betont das Recht auf Selbstbestimmung am Lebensende und warnt davor, dass zusätzliche Hürden schwerkranke oder leidende Menschen unnötig belasten und ihr Leid verlängern könnten. Bürokratische Kontrolle sei kein geeignetes Mittel, um echte Fürsorge zu leisten. Hubertikus fordert stattdessen einen würdevollen, niederschwelligen Zugang begleitet von echter psychologischer Unterstützung.', 'Negative', true, NULL, now(), NULL),

-- 1436: Mehr Schulden für Infrastrukturprojekte
(1436, NULL, 'Hubert Hubertikus spricht sich dafür aus, dass der Staat mehr Schulden aufnimmt, um wichtige Infrastrukturprojekte zu finanzieren. Er argumentiert, dass Investitionen in Schienen, Straßen und digitale Netze die Wirtschaft langfristig stärken und sich damit selbst finanzieren. Bei niedrigen Zinsen sei es volkswirtschaftlich sinnvoll, jetzt zu investieren, statt notwendige Projekte auf spätere Generationen zu verschieben. Für Hubertikus überwiegt der langfristige Nutzen die kurzfristige Erhöhung der Staatsverschuldung.', 'Positive', true, NULL, now(), NULL),
(1436, NULL, 'Hubert Hubertikus warnt vor einer weiteren Erhöhung der Staatsschulden zur Finanzierung von Infrastrukturprojekten. Er sieht darin eine Belastung künftiger Generationen, die für Zinsen und Tilgung aufkommen müssten, ohne selbst über die Ausgaben mitentschieden zu haben. Stattdessen plädiert er für eine Priorisierung bestehender Budgets und effizientere Mittelverwendung. Für Hubertikus muss solide Haushaltsführung Vorrang vor neuen Schulden haben.', 'Negative', true, NULL, now(), NULL),

-- 1437: Geschlechtergerechte Sprache in staatlichen Dokumenten
(1437, NULL, 'Hubert Hubertikus befürwortet die konsequente Verwendung geschlechtergerechter Sprache in staatlichen Dokumenten. Er sieht darin ein wichtiges Signal für Gleichberechtigung und gesellschaftliche Sichtbarkeit aller Geschlechter. Sprache forme Bewusstsein, und öffentliche Institutionen sollten hier eine Vorbildfunktion einnehmen. Für Hubertikus ist dies ein kleiner, aber bedeutsamer Schritt hin zu mehr Inklusion.', 'Positive', true, NULL, now(), NULL),
(1437, NULL, 'Hubert Hubertikus lehnt eine verpflichtende geschlechtergerechte Sprache in staatlichen Dokumenten ab. Er hält die damit verbundenen Formulierungen für umständlich und befürchtet eine erschwerte Verständlichkeit amtlicher Texte, besonders für Menschen mit geringeren Sprachkenntnissen. Sprachliche Vorgaben von oben würden zudem gesellschaftliche Debatten nicht ersetzen können. Hubertikus setzt lieber auf klare, einfache Sprache als auf verpflichtende Genderformen.', 'Negative', true, NULL, now(), NULL),

-- 1438: Steuersenkungen bei Grundnahrungsmitteln
(1438, NULL, 'Hubert Hubertikus befürwortet gezielte Steuersenkungen, um die Preise für Grundnahrungsmittel zu senken. Er sieht darin eine direkte und wirksame Entlastung für Haushalte, die von hohen Lebensmittelpreisen besonders stark betroffen sind. Gerade in Zeiten hoher Inflation sei ein solcher staatlicher Eingriff notwendig, um soziale Härten abzufedern. Für Hubertikus ist leistbares Essen ein Grundrecht, das der Staat aktiv absichern muss.', 'Positive', true, NULL, now(), NULL),
(1438, NULL, 'Hubert Hubertikus ist gegen staatliche Eingriffe in die Preisgestaltung von Grundnahrungsmitteln über gezielte Steuersenkungen. Er befürchtet, dass solche Maßnahmen den Staatshaushalt stark belasten, ohne dass die Einsparungen tatsächlich vollständig an die Konsumentinnen und Konsumenten weitergegeben werden. Markteingriffe könnten zudem Verzerrungen verursachen und langfristig ineffizient sein. Hubertikus setzt stattdessen auf zielgerichtete Direktzahlungen an einkommensschwache Haushalte.', 'Negative', true, NULL, now(), NULL),

-- 1439: Neue Management-Ebene in Schulen
(1439, NULL, 'Hubert Hubertikus hält die Einführung einer neuen Management-Ebene in Schulen für sinnvoll, auch wenn dadurch zusätzliche Bürokratie entsteht. Er argumentiert, dass professionelles Schulmanagement Direktorinnen und Direktoren entlastet und pädagogische sowie administrative Aufgaben klarer trennt. Größere Schulen bräuchten heute Strukturen, die mit jenen mittelständischer Unternehmen vergleichbar sind. Für Hubertikus überwiegt der organisatorische Nutzen den bürokratischen Mehraufwand.', 'Positive', true, NULL, now(), NULL),
(1439, NULL, 'Hubert Hubertikus lehnt eine neue Management-Ebene in Schulen ab, wenn sie zusätzliche Bürokratie erzeugt. Er warnt, dass mehr Verwaltungsebenen wertvolle Ressourcen binden, die besser direkt in den Unterricht und die Schülerinnen und Schüler investiert werden sollten. Zusätzliche Hierarchien könnten zudem Entscheidungswege verlangsamen statt sie zu beschleunigen. Hubertikus plädiert für schlanke Strukturen mit mehr Autonomie für die Pädagoginnen und Pädagogen vor Ort.', 'Negative', true, NULL, now(), NULL),

-- 1440: Befristung von Fahrerlaubnissen nach dem 60. Lebensjahr
(1440, NULL, 'Hubert Hubertikus befürwortet eine Befristung von Fahrerlaubnissen nach dem 60. Lebensjahr. Er argumentiert, dass regelmäßige Überprüfungen der Fahrtauglichkeit im höheren Alter die Verkehrssicherheit für alle Verkehrsteilnehmenden erhöhen. Altersbedingte gesundheitliche Veränderungen könnten die Fahrfähigkeit beeinträchtigen, ohne dass Betroffene dies selbst bemerken. Für Hubertikus ist eine solche Regelung ein verantwortungsvoller Beitrag zur Unfallprävention.', 'Positive', true, NULL, now(), NULL),
(1440, NULL, 'Hubert Hubertikus lehnt eine altersbezogene Befristung von Fahrerlaubnissen ab dem 60. Lebensjahr ab. Er sieht darin eine ungerechtfertigte Diskriminierung, da Fahrtauglichkeit individuell und nicht allein vom Alter abhängig sei. Viele ältere Menschen seien nachweislich sichere und erfahrene Fahrerinnen und Fahrer. Hubertikus fordert stattdessen anlassbezogene statt pauschale Überprüfungen für alle Altersgruppen.', 'Negative', true, NULL, now(), NULL),

-- 1441: Helmpflicht für E-Klein-Roller
(1441, NULL, 'Hubert Hubertikus spricht sich für eine generelle Helmpflicht bei E-Klein-Rollern aus, unabhängig vom Alter. Er verweist auf die hohe Zahl an Kopfverletzungen bei Unfällen mit diesen Fahrzeugen und sieht den Helm als wirksamsten Schutz. Eine einheitliche Regelung für alle Altersgruppen schaffe zudem Klarheit und erleichtere die Durchsetzung. Für Hubertikus überwiegt der Sicherheitsgewinn mögliche Komforteinbußen deutlich.', 'Positive', true, NULL, now(), NULL),
(1441, NULL, 'Hubert Hubertikus ist gegen eine generelle Helmpflicht für alle Nutzerinnen und Nutzer von E-Klein-Rollern. Er hält eine pauschale Pflicht für unverhältnismäßig, insbesondere bei geringen Geschwindigkeiten im innerstädtischen Verkehr. Eine Helmpflicht könnte zudem die Attraktivität dieser umweltfreundlichen Fortbewegungsmittel senken und Menschen zurück ins Auto drängen. Hubertikus setzt lieber auf Aufklärung und freiwillige Nutzung von Schutzausrüstung.', 'Negative', true, NULL, now(), NULL),

-- 1442: Eingriffe in Steuerpolitik bei Energiepreisen
(1442, NULL, 'Hubert Hubertikus befürwortet direkte staatliche Eingriffe in die Steuerpolitik bei stark steigenden Energiepreisen. Er argumentiert, dass der Staat in solchen Krisensituationen rasch handeln müsse, um Haushalte und Unternehmen vor existenzbedrohenden Kostensteigerungen zu schützen. Steuerliche Entlastungen wie eine Senkung der Energiesteuern könnten unmittelbar spürbare Wirkung entfalten. Für Hubertikus ist dies ein legitimes Mittel staatlicher Fürsorge in Ausnahmesituationen.', 'Positive', true, NULL, now(), NULL),
(1442, NULL, 'Hubert Hubertikus lehnt direkte Eingriffe in die Steuerpolitik bei steigenden Energiepreisen ab. Er warnt, dass solche kurzfristigen Maßnahmen den Staatshaushalt belasten und die notwendigen Preissignale für Energieeinsparungen verzerren könnten. Statt in die Steuerpolitik einzugreifen, sollte der Staat gezielt einkommensschwache Haushalte unterstützen. Für Hubertikus sind zielgerichtete Direkthilfen der marktschonendere und effizientere Weg.', 'Negative', true, NULL, now(), NULL),

-- 1443: Verordnungen bei Gefahr im Verzug ohne Nationalrat
(1443, NULL, 'Hubert Hubertikus befürwortet, dass die Regierung in Gefahr-im-Verzug-Situationen Verordnungen ohne vorherige Zustimmung des Nationalrats erlassen darf. Er argumentiert, dass in akuten Krisensituationen rasches Handeln erforderlich sei und langwierige parlamentarische Verfahren wertvolle Zeit kosten würden. Eine nachträgliche parlamentarische Kontrolle reiche aus, um demokratische Legitimität sicherzustellen. Für Hubertikus überwiegt in echten Notlagen die Handlungsfähigkeit des Staates.', 'Positive', true, NULL, now(), NULL),
(1443, NULL, 'Hubert Hubertikus lehnt es ab, dass die Regierung ohne vorherige Zustimmung des Nationalrats Verordnungen bei Gefahr im Verzug erlassen darf. Er warnt vor einer Aushöhlung der parlamentarischen Kontrolle und dem Risiko, dass die Ausnahme zur Regel wird. Gerade in Krisenzeiten sei eine demokratische Legitimation staatlichen Handelns besonders wichtig. Hubertikus fordert stattdessen beschleunigte, aber weiterhin parlamentarisch kontrollierte Verfahren.', 'Negative', true, NULL, now(), NULL),

-- 1444: Verpflichtende Deutschförderklassen
(1444, NULL, 'Hubert Hubertikus hält die Einführung verpflichtender Deutschförderklassen für einen sinnvollen Schritt zur Integration. Er argumentiert, dass solide Deutschkenntnisse die Grundvoraussetzung für schulischen und gesellschaftlichen Erfolg sind. Kinder ohne ausreichende Sprachkenntnisse könnten dem regulären Unterricht nicht folgen und würden dauerhaft benachteiligt bleiben. Für Hubertikus ist gezielte Sprachförderung daher ein Ausdruck echter Chancengleichheit.', 'Positive', true, NULL, now(), NULL),
(1444, NULL, 'Hubert Hubertikus lehnt verpflichtende Deutschförderklassen als sinnvollen Integrationsschritt ab. Er kritisiert, dass die Trennung vom Regelunterricht Kinder stigmatisieren und ihre soziale Integration in die Klassengemeinschaft erschweren könne. Sprachen lerne man am besten im direkten Kontakt mit Gleichaltrigen, nicht isoliert in Sonderklassen. Hubertikus plädiert stattdessen für integrative Sprachförderung innerhalb der regulären Klassen.', 'Negative', true, NULL, now(), NULL),

-- 1445: Weniger Steuern auf Überstundenzuschlag
(1445, NULL, 'Hubert Hubertikus befürwortet niedrigere Steuern auf den Überstundenzuschlag für Arbeitnehmerinnen und Arbeitnehmer. Er sieht darin einen fairen Ausgleich für zusätzliche Arbeitsbelastung und einen Anreiz, mehr zu arbeiten, was dem Fachkräftemangel entgegenwirken könnte. Wer bereit ist, Überstunden zu leisten, solle davon auch spürbar mehr netto behalten. Für Hubertikus ist das eine sinnvolle Maßnahme zur Stärkung der Arbeitsleistung.', 'Positive', true, NULL, now(), NULL),
(1445, NULL, 'Hubert Hubertikus ist gegen eine geringere Besteuerung von Überstundenzuschlägen. Er befürchtet Einnahmeausfälle für den Staat und eine ungleiche Behandlung gegenüber Arbeitnehmerinnen und Arbeitnehmern, die keine Überstunden leisten können, etwa aufgrund von Betreuungspflichten. Zudem könnte ein steuerlicher Anreiz zu mehr Überstunden gesundheitlich bedenklich sein. Hubertikus setzt sich stattdessen für eine generelle Entlastung der Lohnsteuer ein.', 'Negative', true, NULL, now(), NULL),

-- 1446: Politikergehälter an Inflation anpassen
(1446, NULL, 'Hubert Hubertikus befürwortet, dass die Bezahlung von Spitzenpolitikern an die Inflation angepasst wird. Er argumentiert, dass eine automatische Anpassung Transparenz schafft und politisch motivierte Debatten über jährliche Gehaltserhöhungen vermeidet. Zudem sichere sie, dass Politikergehälter real nicht sinken, was auch für andere Berufsgruppen gelte. Für Hubertikus ist eine regelbasierte Anpassung sachlicher als wiederkehrende politische Grundsatzdiskussionen.', 'Positive', true, NULL, now(), NULL),
(1446, NULL, 'Hubert Hubertikus lehnt eine automatische Anpassung der Politikergehälter an die Inflation ab. Er hält es für ein wichtiges Signal, dass sich Spitzenpolitikerinnen und -politiker jedes Jahr aktiv vor der Bevölkerung für Gehaltserhöhungen rechtfertigen müssen. Eine automatische Erhöhung könnte zudem in wirtschaftlich schwierigen Zeiten als unangemessen wahrgenommen werden. Hubertikus fordert stattdessen eine jährliche, transparente politische Entscheidung.', 'Negative', true, NULL, now(), NULL),

-- 1447: Vereinheitlichung der Kündigungsfristen
(1447, NULL, 'Hubert Hubertikus befürwortet eine gesetzliche Vereinheitlichung der Kündigungsfristen. Er sieht darin mehr Klarheit und Rechtssicherheit für Arbeitnehmerinnen und Arbeitgeber, da unterschiedliche Regelungen je nach Branche oder Anstellungsverhältnis oft zu Verwirrung führen. Eine einheitliche Regel erleichtere zudem die Planung bei Jobwechseln. Für Hubertikus ist Vereinfachung hier ein klarer Vorteil für alle Beteiligten.', 'Positive', true, NULL, now(), NULL),
(1447, NULL, 'Hubert Hubertikus lehnt eine generelle Vereinheitlichung der Kündigungsfristen ab. Er argumentiert, dass unterschiedliche Branchen und Beschäftigungsformen unterschiedliche Bedürfnisse haben, die eine einheitliche Regelung nicht abbilden könne. Flexible, branchenspezifische Fristen würden besser den jeweiligen betrieblichen Realitäten entsprechen. Hubertikus plädiert deshalb für differenzierte statt starre gesetzliche Vorgaben.', 'Negative', true, NULL, now(), NULL),

-- 1448: Stärkere Begrenzung von Mieterhöhungen
(1448, NULL, 'Hubert Hubertikus befürwortet eine stärkere gesetzliche Begrenzung von Mieterhöhungen. Er sieht darin einen notwendigen Schutz für Mieterinnen und Mieter angesichts stark steigender Wohnkosten. Wohnen sei ein Grundbedürfnis, das nicht dem freien Spiel der Marktkräfte überlassen werden dürfe. Für Hubertikus ist eine wirksame Mietpreisbremse ein zentraler Baustein sozialer Gerechtigkeit.', 'Positive', true, NULL, now(), NULL),
(1448, NULL, 'Hubert Hubertikus lehnt eine stärkere gesetzliche Begrenzung von Mieterhöhungen ab. Er befürchtet, dass solche Eingriffe Investitionen in den Wohnbau unattraktiv machen und den Wohnungsmangel langfristig verschärfen könnten. Vermieterinnen und Vermieter bräuchten ausreichend Spielraum, um steigende Kosten wie Instandhaltung oder Kredite zu decken. Hubertikus setzt stattdessen auf mehr Wohnbauförderung, um das Angebot zu erhöhen.', 'Negative', true, NULL, now(), NULL),

-- 1449: Kopftuchverbot in Schulen
(1449, NULL, 'Hubert Hubertikus befürwortet ein Kopftuchverbot in Schulen. Er argumentiert, dass Schulen ein neutraler Ort sein sollten, an dem Kinder frei von religiösem oder gesellschaftlichem Druck aufwachsen können. Ein Verbot schütze insbesondere junge Mädchen davor, schon früh in religiös begründete Rollenbilder gedrängt zu werden. Für Hubertikus überwiegt der Schutz der Persönlichkeitsentwicklung von Kindern die individuelle Religionsfreiheit in diesem Kontext.', 'Positive', true, NULL, now(), NULL),
(1449, NULL, 'Hubert Hubertikus lehnt ein Kopftuchverbot in Schulen ab. Er sieht darin einen unverhältnismäßigen Eingriff in die Religionsfreiheit und befürchtet, dass ein solches Verbot muslimische Mädchen und Frauen stigmatisiert und ausgrenzt statt sie zu schützen. Persönliche Kleidungsentscheidungen sollten nicht staatlich reglementiert werden. Hubertikus setzt stattdessen auf Aufklärung und den offenen Dialog mit Familien.', 'Negative', true, NULL, now(), NULL),

-- 1450: Digitalisierung der Gesundheitsversorgung
(1450, NULL, 'Hubert Hubertikus befürwortet eine stärkere Digitalisierung der Gesundheitsversorgung, auch wenn dafür mehr personenbezogene Daten erforderlich sind. Er argumentiert, dass digitale Systeme wie die elektronische Gesundheitsakte Behandlungen effizienter, sicherer und besser koordiniert machen können. Der medizinische Nutzen, etwa durch schnellere Diagnosen und weniger Doppeluntersuchungen, überwiege die Datenschutzbedenken. Für Hubertikus ist eine moderne, digitale Gesundheitsversorgung ein Gewinn für Patientinnen und Patienten.', 'Positive', true, NULL, now(), NULL),
(1450, NULL, 'Hubert Hubertikus ist gegen eine stärkere Digitalisierung der Gesundheitsversorgung, wenn dafür mehr personenbezogene Daten erforderlich sind. Er warnt vor den Risiken des Datenmissbrauchs und davor, dass sensible Gesundheitsdaten in falsche Hände geraten könnten. Der Schutz der Privatsphäre müsse gerade im hochsensiblen Gesundheitsbereich oberste Priorität haben. Hubertikus fordert strengere Datenschutzstandards, bevor die Digitalisierung weiter vorangetrieben wird.', 'Negative', true, NULL, now(), NULL),

-- 1451: Mehr Geld für internationale Entwicklungszusammenarbeit
(1451, NULL, 'Hubert Hubertikus befürwortet, dass Österreich mehr Geld für internationale Entwicklungszusammenarbeit bereitstellt. Er sieht darin eine moralische Verpflichtung wohlhabender Länder, globale Armut, Hunger und Konflikte zu bekämpfen. Investitionen in Entwicklungszusammenarbeit würden zudem langfristig Fluchtursachen reduzieren und die globale Stabilität fördern. Für Hubertikus ist internationale Solidarität ein Ausdruck gelebter Verantwortung.', 'Positive', true, NULL, now(), NULL),
(1451, NULL, 'Hubert Hubertikus lehnt eine Erhöhung der Mittel für internationale Entwicklungszusammenarbeit ab. Er argumentiert, dass angesichts begrenzter Budgets zunächst drängende Probleme im Inland, etwa im Sozial- oder Gesundheitsbereich, priorisiert werden sollten. Zudem seien die Wirksamkeit und Kontrolle vieler Entwicklungsprojekte oft unzureichend belegt. Hubertikus fordert stattdessen eine effizientere Nutzung bestehender Mittel statt einer Erhöhung.', 'Negative', true, NULL, now(), NULL),

-- 1452: Importverbot für Agrarprodukte aus Nicht-EU-Ländern
(1452, NULL, 'Hubert Hubertikus befürwortet ein generelles Importverbot für Agrarprodukte aus Nicht-EU-Ländern. Er argumentiert, dass dies die heimische Landwirtschaft schützt und die regionale Wertschöpfung stärkt. Zudem unterlägen importierte Produkte oft niedrigeren Umwelt- und Tierschutzstandards, was unfairen Wettbewerb bedeute. Für Hubertikus ist Versorgungssicherheit durch heimische Produktion wichtiger als globaler Freihandel.', 'Positive', true, NULL, now(), NULL),
(1452, NULL, 'Hubert Hubertikus lehnt ein generelles Importverbot für Agrarprodukte aus Nicht-EU-Ländern ab. Er warnt vor steigenden Lebensmittelpreisen und einer eingeschränkten Produktvielfalt für Konsumentinnen und Konsumenten. Ein solches Verbot widerspreche zudem internationalen Handelsabkommen und könnte Gegenmaßnahmen anderer Staaten provozieren. Hubertikus setzt stattdessen auf hohe Qualitätsstandards statt pauschaler Importverbote.', 'Negative', true, NULL, now(), NULL),

-- 1453: Staatliche Vorgaben für die Schreibweise in Schulbüchern
(1453, NULL, 'Hubert Hubertikus befürwortet staatliche Vorgaben für die Schreibweise in Schulbüchern. Er sieht darin eine wichtige Maßnahme, um einheitliche und korrekte Sprachstandards im Bildungswesen sicherzustellen. Klare Vorgaben würden zudem Verwirrung bei Schülerinnen und Schülern vermeiden, die mit unterschiedlichen Schreibweisen konfrontiert werden. Für Hubertikus ist sprachliche Einheitlichkeit eine Grundlage für gute Bildung.', 'Positive', true, NULL, now(), NULL),
(1453, NULL, 'Hubert Hubertikus lehnt staatliche Vorgaben für die Schreibweise in Schulbüchern ab. Er hält solche Eingriffe für unnötige Bevormundung und plädiert dafür, sprachliche Entwicklungen den zuständigen pädagogischen und wissenschaftlichen Gremien zu überlassen. Zu starre Vorgaben könnten zudem notwendige sprachliche Weiterentwicklungen blockieren. Hubertikus vertraut lieber auf die fachliche Expertise von Verlagen und Bildungseinrichtungen.', 'Negative', true, NULL, now(), NULL),

-- 1454: Selbstbestimmungsrecht Südtirols
(1454, NULL, 'Hubert Hubertikus befürwortet, dass Österreich das Selbstbestimmungsrecht Südtirols aktiv unterstützt. Er sieht darin eine historische und kulturelle Verpflichtung Österreichs gegenüber der deutschsprachigen Bevölkerung Südtirols. Aktive Unterstützung stärke zudem die Beziehungen zwischen den Regionen und fördere den Minderheitenschutz in Europa. Für Hubertikus ist dies Ausdruck gelebter Verantwortung für die eigene Geschichte.', 'Positive', true, NULL, now(), NULL),
(1454, NULL, 'Hubert Hubertikus lehnt eine aktive Unterstützung des Selbstbestimmungsrechts Südtirols durch Österreich ab. Er warnt vor diplomatischen Spannungen mit Italien und einer Einmischung in innere Angelegenheiten eines Nachbarstaates. Die gute Zusammenarbeit zwischen Österreich und Italien dürfe nicht durch historische Symbolpolitik gefährdet werden. Hubertikus setzt stattdessen auf bestehende, bewährte Autonomieregelungen für Südtirol.', 'Negative', true, NULL, now(), NULL),

-- 1455: Strengere Kontrollen internationaler Steuerabkommen
(1455, NULL, 'Hubert Hubertikus befürwortet strengere Kontrollen im Rahmen internationaler Steuerabkommen zur Bekämpfung von Steuervermeidung. Er argumentiert, dass Steuervermeidung großer Konzerne und Vermögender die Allgemeinheit um wichtige Einnahmen bringt. Wirksame internationale Kontrollen würden für mehr Steuergerechtigkeit sorgen und Wettbewerbsverzerrungen verringern. Für Hubertikus ist konsequente Bekämpfung von Steuervermeidung eine Frage der Fairness.', 'Positive', true, NULL, now(), NULL),
(1455, NULL, 'Hubert Hubertikus ist skeptisch gegenüber strengeren internationalen Kontrollen zur Bekämpfung von Steuervermeidung. Er befürchtet einen erheblichen bürokratischen Mehraufwand für Unternehmen und eine Schwächung des Wirtschaftsstandorts durch zu starre internationale Vorgaben. Steuerpolitik solle primär in nationaler Hoheit bleiben statt international vereinheitlicht zu werden. Hubertikus plädiert für gezielte statt pauschale Kontrollmaßnahmen.', 'Negative', true, NULL, now(), NULL),

-- 1456: Finanzielle Sanktionen für Bundesländer bei verfehlten Klimazielen
(1456, NULL, 'Hubert Hubertikus befürwortet finanzielle Sanktionen für Bundesländer, die ihre nationalen Klimaziele verfehlen. Er argumentiert, dass klare Konsequenzen notwendig sind, um tatsächliche Fortschritte beim Klimaschutz zu erzwingen und Trittbrettfahrer-Verhalten zu verhindern. Ohne wirksame Sanktionen blieben Klimaziele häufig bloße Absichtserklärungen. Für Hubertikus ist finanzieller Druck ein notwendiges Instrument, um die Klimakrise ernsthaft zu bekämpfen.', 'Positive', true, NULL, now(), NULL),
(1456, NULL, 'Hubert Hubertikus lehnt finanzielle Sanktionen für Bundesländer bei verfehlten Klimazielen ab. Er warnt, dass solche Strafen ohnehin knappe Budgets weiter belasten und dringend benötigte Investitionen in Klimaschutzmaßnahmen erschweren würden. Kooperation und gezielte Förderungen seien wirksamer als Bestrafung. Hubertikus setzt stattdessen auf gemeinsame Zielvereinbarungen zwischen Bund und Ländern.', 'Negative', true, NULL, now(), NULL),

-- 1457: Dienstleistungen von Behörden/Banken auch ohne Internetzugang
(1457, NULL, 'Hubert Hubertikus befürwortet eine Verpflichtung für Behörden und Banken, ihre Dienstleistungen auch ohne Internetzugang anzubieten. Er betont, dass nicht alle Menschen, insbesondere ältere oder ländliche Bevölkerungsgruppen, gleichermaßen Zugang zu digitalen Angeboten haben. Der Zugang zu grundlegenden staatlichen und finanziellen Dienstleistungen dürfe nicht von digitaler Kompetenz abhängen. Für Hubertikus ist dies eine Frage sozialer Teilhabe und Gerechtigkeit.', 'Positive', true, NULL, now(), NULL),
(1457, NULL, 'Hubert Hubertikus lehnt eine gesetzliche Verpflichtung ab, Dienstleistungen von Behörden und Banken zwingend auch ohne Internetzugang anzubieten. Er argumentiert, dass dies die Digitalisierung verlangsamt und unnötige Doppelstrukturen sowie hohe Kosten verursacht. Die Ressourcen sollten stattdessen in die Verbesserung der digitalen Zugänglichkeit und Barrierefreiheit investiert werden. Hubertikus setzt auf gezielte Unterstützungsangebote statt auf eine generelle Offline-Pflicht.', 'Negative', true, NULL, now(), NULL),

-- 1458: Investitionen in die Gasinfrastruktur
(1458, NULL, 'Hubert Hubertikus befürwortet Investitionen des Staates in die Gasinfrastruktur, um die Versorgungssicherheit zu garantieren. Er argumentiert, dass Gas in der Übergangsphase zu erneuerbaren Energien weiterhin eine wichtige Rolle spielt und ein Ausfall der Versorgung gravierende wirtschaftliche und soziale Folgen hätte. Eine verlässliche Infrastruktur sei die Grundlage für Energiesicherheit in Krisenzeiten. Für Hubertikus überwiegt kurzfristig die Versorgungssicherheit langfristige klimapolitische Bedenken.', 'Positive', true, NULL, now(), NULL),
(1458, NULL, 'Hubert Hubertikus lehnt weitere staatliche Investitionen in die Gasinfrastruktur ab. Er warnt, dass solche Investitionen die Abhängigkeit von fossilen Energieträgern verlängern und dem Ziel der Klimaneutralität entgegenwirken. Mittel, die in Gasinfrastruktur fließen, fehlten zudem beim notwendigen Ausbau erneuerbarer Energien. Hubertikus fordert stattdessen eine konsequente Investition in nachhaltige Versorgungssicherheit.', 'Negative', true, NULL, now(), NULL),

-- 1459: Stärkere Kontrolle von Subventionen an NGOs
(1459, NULL, 'Hubert Hubertikus befürwortet eine stärkere Kontrolle von Subventionen an NGOs. Er argumentiert, dass Transparenz bei der Verwendung öffentlicher Gelder unerlässlich ist, um Missbrauch zu verhindern und das Vertrauen der Steuerzahlerinnen und Steuerzahler zu sichern. Klare Kontrollmechanismen würden zudem sicherstellen, dass Fördergelder tatsächlich ihren angegebenen Zweck erfüllen. Für Hubertikus ist Rechenschaftspflicht bei öffentlichen Mitteln unverzichtbar.', 'Positive', true, NULL, now(), NULL),
(1459, NULL, 'Hubert Hubertikus lehnt eine stärkere Kontrolle von Subventionen an NGOs ab. Er warnt, dass zusätzliche bürokratische Auflagen die wichtige gesellschaftliche Arbeit vieler zivilgesellschaftlicher Organisationen erschweren und ihre Unabhängigkeit gefährden könnten. Bereits bestehende Prüf- und Berichtspflichten seien ausreichend, um Transparenz sicherzustellen. Hubertikus sieht in verschärften Kontrollen eher ein Misstrauensvotum gegenüber der Zivilgesellschaft.', 'Negative', true, NULL, now(), NULL),

-- 1460: Strafbarkeit von Deepfakes im Strafgesetzbuch
(1460, NULL, 'Hubert Hubertikus befürwortet die Verankerung der Strafbarkeit von Deepfakes im Strafgesetzbuch. Er argumentiert, dass manipulierte Medieninhalte erheblichen persönlichen und gesellschaftlichen Schaden anrichten können, etwa durch Rufschädigung oder Desinformation. Ein klarer gesetzlicher Rahmen schaffe Rechtssicherheit für Betroffene und ermögliche eine wirksame Strafverfolgung. Für Hubertikus ist gesetzlicher Schutz vor Deepfakes angesichts der technologischen Entwicklung dringend notwendig.', 'Positive', true, NULL, now(), NULL),
(1460, NULL, 'Hubert Hubertikus ist skeptisch gegenüber einer eigenen strafrechtlichen Regelung für Deepfakes. Er argumentiert, dass bestehende Gesetze zu Verleumdung, Betrug und Persönlichkeitsrechten bereits ausreichend Schutz bieten könnten. Eine neue, spezifische Regelung berge zudem das Risiko unklarer Abgrenzungen, etwa gegenüber satirischer oder künstlerischer Nutzung. Hubertikus fordert stattdessen eine sorgfältige Prüfung, ob bestehende Gesetze angepasst statt neue geschaffen werden sollten.', 'Negative', true, NULL, now(), NULL),

-- 1461: Ressourcen für Schulung von Polizei und Justiz zu digitaler Gewalt
(1461, NULL, 'Hubert Hubertikus befürwortet mehr staatliche Ressourcen für die Schulung von Polizei und Justiz im Bereich digitaler Gewalt. Er argumentiert, dass Cybermobbing, Hasspostings und Online-Belästigung zunehmend reale und schwerwiegende Folgen für Betroffene haben. Gut geschulte Behörden seien entscheidend, um solche Delikte konsequent zu verfolgen und Opfer wirksam zu schützen. Für Hubertikus ist Investition in digitale Kompetenz bei Polizei und Justiz überfällig.', 'Positive', true, NULL, now(), NULL),
(1461, NULL, 'Hubert Hubertikus sieht zusätzliche Ressourcen für Polizei und Justiz speziell im Bereich digitaler Gewalt kritisch. Er argumentiert, dass angesichts begrenzter Budgets andere Bereiche wie Gewaltschutz oder Prävention im realen Leben dringlicher seien. Zudem könnten bestehende Schulungsprogramme durch bessere Organisation effizienter genutzt werden, ohne zusätzliche Mittel zu benötigen. Hubertikus fordert eine gesamtheitliche Prioritätensetzung statt isolierter Sonderinvestitionen.', 'Negative', true, NULL, now(), NULL),

-- 1462: Schieneninfrastruktur vs. Straßenbau
(1462, NULL, 'Hubert Hubertikus befürwortet, dass staatliche Mittel primär in den Ausbau der Schieneninfrastruktur statt in den Straßenbau fließen. Er argumentiert, dass die Schiene eine klimafreundlichere und langfristig effizientere Mobilitätsform darstellt. Ein starkes Schienennetz reduziere den Individualverkehr und trage entscheidend zur Erreichung der Klimaziele bei. Für Hubertikus ist dies ein notwendiger Schritt für eine nachhaltige Verkehrswende.', 'Positive', true, NULL, now(), NULL),
(1462, NULL, 'Hubert Hubertikus lehnt eine einseitige Priorisierung der Schieneninfrastruktur gegenüber dem Straßenbau ab. Er verweist darauf, dass viele ländliche Regionen weiterhin auf ein funktionierendes Straßennetz angewiesen sind, da eine flächendeckende Schienenanbindung nicht überall wirtschaftlich möglich ist. Eine ausgewogene Verkehrsinfrastruktur berücksichtige die unterschiedlichen Bedürfnisse von Stadt und Land. Hubertikus fordert eine bedarfsgerechte statt einseitige Mittelverteilung.', 'Negative', true, NULL, now(), NULL),

-- 1463: Ende der Wirtschaftssanktionen gegen Russland
(1463, NULL, 'Hubert Hubertikus befürwortet ein vollständiges Ende der Wirtschaftssanktionen Österreichs gegen Russland. Er argumentiert, dass die Sanktionen der österreichischen Wirtschaft erheblich schaden, etwa durch hohe Energiepreise und den Verlust wichtiger Handelsbeziehungen, ohne den beabsichtigten politischen Effekt zu erzielen. Diplomatische statt wirtschaftlicher Mittel seien der bessere Weg zur Konfliktlösung. Für Hubertikus überwiegen die wirtschaftlichen Schäden den politischen Nutzen der Sanktionen.', 'Positive', true, NULL, now(), NULL),
(1463, NULL, 'Hubert Hubertikus lehnt eine vollständige Beendigung der Wirtschaftssanktionen gegen Russland entschieden ab. Er betont, dass die Sanktionen eine wichtige internationale Reaktion auf den völkerrechtswidrigen Angriffskrieg darstellen und ein Ende ein falsches Signal der Nachgiebigkeit senden würde. Österreich müsse als Teil der internationalen Gemeinschaft Solidarität mit der Ukraine zeigen. Hubertikus sieht die Sanktionen als notwendiges Mittel, um Druck auf Russland aufrechtzuerhalten.', 'Negative', true, NULL, now(), NULL),

-- 1464: Strengere Gesetze gegen Desinformation im Internet
(1464, NULL, 'Hubert Hubertikus befürwortet strengere Gesetze zur Bekämpfung von Desinformation im Internet. Er argumentiert, dass gezielte Falschinformationen die demokratische Meinungsbildung gefährden und gesellschaftliche Spaltung fördern können. Ein klarer gesetzlicher Rahmen sei notwendig, um Plattformen stärker in die Verantwortung zu nehmen. Für Hubertikus ist der Schutz der demokratischen Öffentlichkeit wichtiger als Bedenken hinsichtlich möglicher Regulierung.', 'Positive', true, NULL, now(), NULL),
(1464, NULL, 'Hubert Hubertikus lehnt strengere gesetzliche Regelungen gegen Desinformation im Internet ab. Er warnt vor der Gefahr, dass solche Gesetze zur Einschränkung der Meinungsfreiheit missbraucht werden könnten, insbesondere wenn die Grenze zwischen Desinformation und legitimer Kritik unklar gezogen wird. Bildung und Medienkompetenz seien wirksamere und weniger riskante Mittel gegen Desinformation. Hubertikus setzt auf Aufklärung statt auf staatliche Eingriffe in die Meinungsfreiheit.', 'Negative', true, NULL, now(), NULL),

-- 1465: Alleinige Koordination von Krisen- und Blackout-Maßnahmen durch den Bund
(1465, NULL, 'Hubert Hubertikus befürwortet, dass der Bund allein die Koordination von Krisen- und Blackout-Maßnahmen übernimmt. Er argumentiert, dass eine zentrale Steuerung in Notfällen schnelleres und einheitlicheres Handeln ermöglicht als eine Aufteilung der Verantwortung auf mehrere Ebenen. Uneinheitliche Zuständigkeiten könnten in echten Krisensituationen wertvolle Zeit kosten. Für Hubertikus ist klare zentrale Verantwortung entscheidend für effektives Krisenmanagement.', 'Positive', true, NULL, now(), NULL),
(1465, NULL, 'Hubert Hubertikus lehnt eine alleinige Zuständigkeit des Bundes für die Koordination von Krisen- und Blackout-Maßnahmen ab. Er betont, dass Länder und Gemeinden über wichtiges lokales Wissen verfügen, das für eine wirksame Krisenbewältigung unverzichtbar ist. Eine enge Zusammenarbeit aller Ebenen sei effektiver als zentralistische Alleinverantwortung. Hubertikus fordert stattdessen klar abgestimmte, gemeinsame Krisenpläne von Bund, Ländern und Gemeinden.', 'Negative', true, NULL, now(), NULL),

-- 1466: Aktiver Druck Österreichs gegen die Todesstrafe
(1466, NULL, 'Hubert Hubertikus befürwortet, dass Österreich aktiv Druck auf andere Staaten ausübt, um die Todesstrafe zu verhindern. Er sieht die Ablehnung der Todesstrafe als fundamentalen Ausdruck der Menschenrechte, für die sich Österreich international einsetzen sollte. Aktives diplomatisches Engagement könne dazu beitragen, weltweit Menschenleben zu retten. Für Hubertikus ist dies eine moralische Verpflichtung eines Landes, das sich zu den Menschenrechten bekennt.', 'Positive', true, NULL, now(), NULL),
(1466, NULL, 'Hubert Hubertikus ist skeptisch gegenüber aktivem österreichischem Druck auf andere Staaten in Bezug auf die Todesstrafe. Er warnt vor diplomatischen Spannungen und dem Vorwurf der Einmischung in innere Angelegenheiten souveräner Staaten. Zudem sei fraglich, ob solcher Druck tatsächlich wirksam ist oder eher Abwehrreaktionen hervorruft. Hubertikus setzt lieber auf multilaterale, von internationalen Organisationen getragene Initiativen statt auf bilateralen Druck.', 'Negative', true, NULL, now(), NULL);

COMMIT;
